mapper.select:
SELECT id,
       platform,
       bot_id          AS botId,
       group_id        AS groupId,
       from_persona_id AS fromPersonaId,
       to_persona_id   AS toPersonaId,
       operator,
       reason,
       switched_at     AS switchedAt
FROM group_persona_history
WHERE platform = #{platform}
  AND bot_id = #{botId}
  AND group_id = #{groupId}
ORDER BY switched_at DESC, id DESC
    LIMIT #{limit}
OFFSET #{offset}

SELECT COUNT(*)
FROM group_persona_history
WHERE platform = #{platform}
  AND bot_id = #{botId}
  AND group_id = #{groupId}
